  end

  @doc """
  Finish a dialect-built request through the bound host (AUTH-10)

  and sign it.  With no host this is `make_json_request` — every
  dialect routes its wire requests through here so a host never needs
  a dialect branch.

  ## Parameters

  - `method` (String.t() keyword-only, required)
  - `url` (String.t() keyword-only, required)
  - `headers` ((%{optional(String.t()) => String.t()} | list({String.t(), String.t()})) | nil keyword-only default: None)
  - `params` (%{optional(String.t()) => term()} | nil keyword-only default: None)
  - `payload` (term() keyword-only default: None)
  - `body` (binary() | nil keyword-only default: None)
  - `endpoint` (String.t() | nil keyword-only default: None)
  - `stream` (boolean() keyword-only default: False)
  - `model` (String.t() | nil keyword-only default: None)
  - `connect_timeout` (float() | nil keyword-only default: None)
  - `read_timeout` (float() | nil keyword-only default: None)
  - `write_timeout` (float() | nil keyword-only default: None)

  ## Returns

  - `term()`
  """
  @spec _emit(SnakeBridge.Ref.t(), keyword()) :: {:ok, term()} | {:error, Snakepit.Error.t()}
  def _emit(ref, opts \\ []) do
    kw_keys = opts |> Keyword.keys() |> Enum.map(&to_string/1)
    missing_kw = ["method", "url"] |> Enum.reject(&(&1 in kw_keys))

    if missing_kw != [] do
      raise ArgumentError,
            "Missing required keyword-only arguments: " <> Enum.join(missing_kw, ", ")
    end

    SnakeBridge.Runtime.call_method(ref, :_emit, [], opts)
  end

